  const xrBdf = (s) => { const m = String(s || '').match(/(?:([0-9a-f]{4,8}):)?([0-9a-f]{2}):([0-9a-f]{2})\.([0-7])/i); return m ? `${(m[1] || '0000').slice(-4)}:${m[2]}:${m[3]}.${m[4]}`.toLowerCase() : ''; };
